-- Run this ENTIRE file in Neon as the application table owner, through COMMIT.
-- Source: Book3_84_Incomplete_Collections (1).xlsx, original Excel row identifiers retained.
-- 40 rows have complete import fields; 44 still lack values and remain pending.
-- Already imported rows are never duplicated or overwritten.
-- Uses the previously corrected fundraiser identities and preserves their JAH codes.
-- Cash and sequential assumed receipt numbers follow the existing historical-import convention.
-- Exact recorded commissions are preserved; percentages are derived only for display.
-- Conflicting or unknown original book references remain pending; unrelated stock is never substituted.
-- No existing book numbers, receipt ranges, issued document numbers, RLS or grants are changed.
BEGIN;
SET LOCAL lock_timeout = '10s';

DO $corrected84$
DECLARE
  actor public.people; stock public.books; returned public.book_returns;
  src record; group_row record; line record; old_import public.legacy_collection_imports;
  person_uuid uuid; edition_uuid uuid; area_uuid uuid; book_uuid uuid;
  assignment_uuid uuid; case_uuid uuid; return_uuid uuid; receipt_uuid uuid;
  matched integer; receipt_no integer; added_receipts integer; used_receipts integer; last_receipt integer;
  new_total bigint; new_commission bigint; prior_total bigint; prior_commission bigint;
  first_day date; last_day date; first_entry date; last_entry date; final_condition text;
  areas_json jsonb; name_text text; code_text text; phone_text text; whatsapp_text text; address_text text;
  staff_text text; note_text text; problem text; failure_state text; return_before jsonb;
  next_ordinal integer;
BEGIN
  IF current_user='dms_runtime' OR EXISTS (
    SELECT 1 FROM pg_catalog.pg_class WHERE oid IN (
      'public.people'::regclass,'public.fundraisers'::regclass,'public.master_records'::regclass,
      'public.books'::regclass,'public.book_assignments'::regclass,'public.book_cases'::regclass,
      'public.book_returns'::regclass,'public.book_receipts'::regclass,'public.legacy_collection_imports'::regclass,
      'public.leftover_books'::regclass)
    AND relowner<>current_user::regrole::oid
  ) THEN RAISE EXCEPTION 'Run the entire file as the application table owner'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('dms:import:Book3_v1'));
  PERFORM pg_advisory_xact_lock(hashtext('dms:book-stock:write'));
  LOCK TABLE public.people,public.fundraisers,public.master_records,public.books,
    public.book_assignments,public.book_cases,public.book_returns,public.book_receipts,
    public.legacy_collection_imports,public.leftover_books,public.book_flags,public.receipt_issues
    IN SHARE ROW EXCLUSIVE MODE;
  SELECT * INTO actor FROM public.people WHERE role='SUPER_ADMIN' AND status='ACTIVE'
    AND deleted_at IS NULL ORDER BY created_at,id LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'An active Super Admin is required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid='public.book_returns'::regclass
    AND attname='historical_commission_paise' AND NOT attisdropped) THEN
    RAISE EXCEPTION 'Apply manual-exact-historical-commissions.sql first';
  END IF;
  PERFORM set_config('app.person_id',actor.id::text,true);
  PERFORM set_config('app.auth_user_id',coalesce(actor.auth_user_id::text,''),true);
  PERFORM set_config('app.role','SUPER_ADMIN',true);
  PERFORM set_config('app.change_reason','Corrected historical workbook: 84 incomplete collections',true);

  CREATE TEMP TABLE dms_corrected84 ON COMMIT DROP AS
    SELECT x.*,NULL::uuid AS person_id,NULL::uuid AS edition_id,NULL::uuid AS area_id,
      NULL::uuid AS book_id,false AS previously_imported,false AS newly_imported,
      ''::text AS result,''::text AS allocation_note
    FROM jsonb_to_recordset($corrected84_payload$
