aH","condition":"Continue","amount_paise":625000,"commission_paise":312500,"entry_by":"S R Husain","note":"","corrections":{"Entry Date":"2024-05-14","Book No.":258,"Type":"Common","Edition":"6th","Fundraiser Name":"Aasik Khan","Address":"Kalinag","District":"Jagatsinghpur","State":"Odisha","Collection Area":"JaH","Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-05-03","Book Condition":"Continue","Collection Amount":6250,"Commission Amount":3125,"Entry by":"S R Husain"},"original":{"Entry Date":"2024-05-14 00:00:00","Book No.":258,"Type":"Common","Edition":"6th","Fundraiser Name":"M Ashiq Khan","Address":"Kalinag","District":"Jagatsinghpur","State":"Odisha","Collection Area":null,"Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-05-03 00:00:00","Book Condition":"Continue","Collection Amount":6250,"Commission Amount":3125,"Entry by":"S R Husain"}},{"source_row":309,"canonical_name":"Ramzani","book_number":209,"book_type":"REGULAR","token_paise":null,"edition_number":6,"entry_date":"2024-08-22","collection_date":"2024-07-07","collection_area":"Cuttack","condition":"Finished","amount_paise":1065000,"commission_paise":0,"entry_by":"S R Husain","note":"Book condition corrected to Finished by user; collection INR 10650 preserved.","corrections":{"Entry Date":"2024-08-22","Book No.":209,"Type":"Common","Edition":"6th","Fundraiser Name":"Ramzani","Address":"Cuttack","District":"Cuttack","State":"Odisha","Collection Area":"Cuttack","Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-07-07","Book Condition":"Finished","Collection Amount":10650,"Commission Amount":0,"Entry by":"S R Husain"},"original":{"Entry Date":"2024-08-22 00:00:00","Book No.":209,"Type":"Common","Edition":"6th","Fundraiser Name":"Ramzani","Address":"Cuttack","District":"Cuttack","State":"Odisha","Collection Area":null,"Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-07-07 00:00:00","Book Condition":"Not Used","Collection Amount":10650,"Commission Amount":0,"Entry by":"S R Husain"}},{"source_row":310,"canonical_name":"Aasik Khan","book_number":79,"book_type":"REGULAR","token_paise":null,"edition_number":6,"entry_date":"2024-05-14","collection_date":"2024-04-29","collection_area":"JaH","condition":"Finished","amount_paise":559000,"commission_paise":279500,"entry_by":"S R Husain","note":"","corrections":{"Entry Date":"2024-05-14","Book No.":79,"Type":"Common","Edition":"6th","Fundraiser Name":"Aasik Khan","Address":"Kalinag","District":"Jagatsinghpur","State":"Odisha","Collection Area":"JaH","Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-04-29","Book Condition":"Finished","Collection Amount":5590,"Commission Amount":2795,"Entry by":"S R Husain"},"original":{"Entry Date":"2024-05-14 00:00:00","Book No.":79,"Type":"Common","Edition":"6th","Fundraiser Name":"M Ashiq Khan","Address":"Kalinag","District":"Jagatsinghpur","State":"Odisha","Collection Area":null,"Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-04-29 00:00:00","Book Condition":"Finished","Collection Amount":5590,"Commission Amount":2795,"Entry by":"S R Husain"}},{"source_row":318,"canonical_name":"Ahmad Raza","book_number":173,"book_type":"REGULAR","token_paise":null,"edition_number":6,"entry_date":"2024-08-22","collection_date":"2024-06-04","collection_area":"Daryapur","condition":"Continue","amount_paise":93000,"commission_paise":46500,"entry_by":"S R Husain","note":"","corrections":{"Entry Date":"2024-08-22","Book No.":173,"Type":"Common","Edition":"6th","Fundraiser Name":"Ahmad Raza","Address":"Daryapur","District":"Jagatsinghpur","State":"Odisha","Collection Area":"Daryapur","Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-06-04","Book Condition":"Continue","Collection Amount":930,"Commission Amount":465,"Entry by":"S R Husain"},"original":{"Entry Date":"2024-08-22 00:00:00","Book No.":173,"Type":"Common","Edition":"6th","Fundraiser Name":"Ahmad Raza","Address":"Daryapur","District":"Jagatsinghpur","State":"Odisha","Collection Area":null,"Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-06-04 00:00:00","Book Condition":"Continue","Collection Amount":930,"Commission Amount":465,"Entry by":"S R Husain"}},{"source_row":320,"canonical_name":"Hafiz Azhar","book_number":170,"book_type":"REGULAR","token_paise":null,"edition_number":6,"entry_date":"2024-08-22","collection_date":"2024-07-16","collection_area":"Sompur","condition":"Finished","amount_paise":300000,"commission_paise":0,"entry_by":"S R Husain","note":"","corrections":{"Entry Date":"2024-08-22","Book No.":170,"Type":"Common","Edition":"6th","Fundraiser Name":"Hafiz Azhar","Address":"Sompur","District":"Cuttack","State":"Odisha","Collection Area":"Sompur","Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-07-16","Book Condition":"Finished","Collection Amount":3000,"Commission Amount":0,"Entry by":"S R Husain"},"original":{"Entry Date":"2024-08-22 00:00:00","Book No.":170,"Type":"Common","Edition":"6th","Fundraiser Name":"Hafiz Azhar","Address":"Sompur","District":"Cuttack","State":"Odisha","Collection Area":null,"Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-07-16 00:00:00","Book Condition":"Finished","Collection Amount":3000,"Commission Amount":0,"Entry by":"S R Husain"}},{"source_row":321,"canonical_name":"Mohammad Imteyaz","book_number":176,"book_type":"REGULAR","token_paise":null,"edition_number":6,"entry_date":"2024-08-22","collection_date":"2024-07-16","collection_area":"Goda","condition":"Finished","amount_paise":280000,"commission_paise":0,"entry_by":"S R Husain","note":"","corrections":{"Entry Date":"2024-08-22","Book No.":176,"Type":"Common","Edition":"6th","Fundraiser Name":"Mohammad Imteyaz","Address":"Goda","District":"Jagatsinghpur","State":"Odisha","Collection Area":"Goda","Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-07-16","Book Condition":"Finished","Collection Amount":2800,"Commission Amount":0,"Entry by":"S R Husain"},"original":{"Entry Date":"2024-08-22 00:00:00","Book No.":176,"Type":"Common","Edition":"6th","Fundraiser Name":"Mohammad Imteyaz","Address":"Goda","District":"Jagatsinghpur","State":"Odisha","Collection Area":null,"Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-07-16 00:00:00","Book Condition":"Finished","Collection Amount":2800,"Commission Amount":0,"Entry by":"S R Husain"}},{"source_row":322,"canonical_name":"Abdul Hafiz","book_number":175,"book_type":"REGULAR","token_paise":null,"edition_number":6,"entry_date":"2024-08-22","collection_date":"2024-07-16","collection_area":"Kalabedi","condition":"Finished","amount_paise":420000,"commission_paise":100000,"entry_by":"S R Husain","note":"","corrections":{"Entry Date":"2024-08-22","Book No.":175,"Type":"Common","Edition":"6th","Fundraiser Name":"Abdul Hafiz","Address":"Kalabedi","District":"Jagatsinghpur","State":"Odisha","Collection Area":"Kalabedi","Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-07-16","Book Condition":"Finished","Collection Amount":4200,"Commission Amount":1000,"Entry by":"S R Husain"},"original":{"Entry Date":"2024-08-22 00:00:00","Book No.":175,"Type":"Common","Edition":"6th","Fundraiser Name":"Abdul Hafiz","Address":"Kalabedi","District":"Jagatsinghpur","State":"Odisha","Collection Area":null,"Mobile No":null,"WhatsApp No.":null,"Collection Date":"2024-07-16 00:00:00","Book Condition":"Finished","Collection Amount":4200,"Commission Amount":1000,"Entry by":"S R Husain"}}]
$corrected84_payload$::jsonb) AS x(
      source_row integer,canonical_name text,book_number integer,book_type text,token_paise integer,
      edition_number integer,entry_date text,collection_date text,collection_area text,condition text,
      amount_paise bigint,commission_paise bigint,entry_by text,note text,corrections jsonb,original jsonb
    );
  ALTER TABLE pg_temp.dms_corrected84 ADD PRIMARY KEY(source_row);
  IF (SELECT count(*) FROM pg_temp.dms_corrected84)<>84 THEN RAISE EXCEPTION 'Expected exactly 84 source rows'; END IF;

  -- Read spreadsheet dates as text first: malformed cells must become pending rows,
  -- not abort jsonb_to_recordset before the per-row validation can run.
  ALTER TABLE pg_temp.dms_corrected84 RENAME COLUMN entry_date TO entry_date_raw;
  ALTER TABLE pg_temp.dms_corrected84 RENAME COLUMN collection_date TO collection_date_raw;
  ALTER TABLE pg_temp.dms_corrected84 ADD COLUMN entry_date date, ADD COLUMN collection_date date;
  FOR src IN SELECT source_row,entry_date_raw,collection_date_raw FROM pg_temp.dms_corrected84 LOOP
    BEGIN
      UPDATE pg_temp.dms_corrected84 SET entry_date=CASE
        WHEN btrim(src.entry_date_raw) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN btrim(src.entry_date_raw)::date END
        WHERE source_row=src.source_row;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN NULL;
    END;
    BEGIN
      UPDATE pg_temp.dms_corrected84 SET collection_date=CASE
        WHEN btrim(src.collection_date_raw) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN btrim(src.collection_date_raw)::date END
        WHERE source_row=src.source_row;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN NULL;
    END;
  END LOOP;

  -- Stage corrections separately. Original imported snapshots and hashes remain immutable.
  FOR src IN SELECT * FROM pg_temp.dms_corrected84 ORDER BY source_row LOOP
    SELECT * INTO old_import FROM public.legacy_collection_imports
      WHERE source_key='Book3_v1:Sheet1:'||src.source_row::text;
    IF FOUND THEN
      IF old_import.source_row<>src.source_row OR old_import.source_hash IS DISTINCT FROM
        encode(sha256(convert_to(old_import.source_data::text,'UTF8')),'hex') THEN
        RAISE EXCEPTION 'Source provenance is inconsistent at original Excel row %',src.source_row;
      END IF;
      IF old_import.status='IMPORTED' THEN
        UPDATE pg_temp.dms_corrected84 SET previously_imported=true,result='Already imported; unchanged'
          WHERE source_row=src.source_row;
        CONTINUE;
      END IF;
    ELSE
      INSERT INTO public.legacy_collection_imports(source_key,source_row,source_hash,source_data,reason)
      VALUES('Book3_v1:Sheet1:'||src.source_row::text,src.source_row,
        encode(sha256(convert_to(src.original::text,'UTF8')),'hex'),src.original,'Awaiting corrected import');
    END IF;
    UPDATE public.legacy_collection_imports SET source_corrections=
      coalesce(source_corrections,'{}'::jsonb)||jsonb_strip_nulls(src.corrections)||
      jsonb_build_object('_correctionWorkbook','Book3_84_Incomplete_Collections (1).xlsx','_correctionNote',src.note)
      WHERE source_key='Book3_v1:Sheet1:'||src.source_row::text;
    problem:=concat_ws('; ',
      CASE WHEN coalesce(btrim(src.canonical_name),'')='' THEN 'Missing fundraiser name' END,
      CASE WHEN src.book_number IS NULL OR src.book_number<=0 THEN 'Missing/invalid original book number' END,
      CASE WHEN src.book_type IS NULL OR src.book_type NOT IN ('REGULAR','TOKEN') THEN 'Missing/unsupported book type' END,
      CASE WHEN src.edition_number IS NULL OR src.edition_number<=0 THEN 'Missing edition' END,
      CASE WHEN src.entry_date IS NULL THEN 'Missing/invalid entry date: '||coalesce(src.entry_date_raw,'blank') END,
      CASE WHEN src.collection_date IS NULL THEN 'Missing/invalid collection date: '||coalesce(src.collection_date_raw,'blank') END,
      CASE WHEN coalesce(btrim(src.collection_area),'')='' THEN 'Missing collection area' END,
      CASE WHEN coalesce(btrim(src.entry_by),'')='' THEN 'Missing entry by' END,
      CASE WHEN src.amount_paise IS NULL THEN 'Missing collection amount; not assumed zero' END,
      CASE WHEN src.commission_paise IS NULL THEN 'Missing commission amount; not assumed zero' END);
    IF problem='' AND (src.amount_paise NOT BETWEEN 0 AND 999999999999 OR
      src.commission_paise NOT BETWEEN 0 AND src.amount_paise OR
      src.entry_date>(now() AT TIME ZONE 'Asia/Kolkata')::date OR
      src.collection_date>(now() AT TIME ZONE 'Asia/Kolkata')::date OR
      src.condition NOT IN ('Finished','Continue','Not Used','Blank') OR
      (src.book_type='TOKEN' AND src.token_paise NOT IN (1000,5000,10000)) OR
      (src.condition='Not Used' AND (src.amount_paise<>0 OR src.commission_paise<>0))) THEN
      problem:='Invalid date, financial value, denomination or conflicting Not Used condition';
    END IF;
    IF problem<>'' THEN
      UPDATE pg_temp.dms_corrected84 SET result=problem WHERE source_row=src.source_row;
      CONTINUE;
    END IF;
    -- Names below are the row-specific canonical names from the previous reviewed identity correction.
    -- No fuzzy identity merges, new profiles, code changes, or deleted-profile restorations.
    SELECT count(*),(array_agg(p.id))[1] INTO matched,person_uuid
      FROM public.people p JOIN public.fundraisers f ON f.person_id=p.id
      WHERE p.role='COLLECTOR' AND p.deleted_at IS NULL AND f.deleted_at IS NULL
        AND lower(regexp_replace(btrim(p.full_name),'[[:space:]]+',' ','g'))=
          lower(regexp_replace(btrim(src.canonical_name),'[[:space:]]+',' ','g'));
    IF matched<>1 THEN
      UPDATE pg_temp.dms_corrected84 SET result='No unique existing canonical fundraiser; identity review required'
        WHERE source_row=src.source_row; CONTINUE;
    END IF;
    SELECT count(*),(array_agg(m.id))[1] INTO matched,edition_uuid FROM public.master_records m
      WHERE m.kind='EDITION' AND m.deleted_at IS NULL AND m.edition_number=src.edition_number
        AND m.edition_book_type=src.book_type
        AND m.edition_token_value_paise IS NOT DISTINCT FROM src.token_paise;
    IF matched<>1 THEN
      UPDATE pg_temp.dms_corrected84 SET result='No unique existing edition and denomination'
        WHERE source_row=src.source_row; CONTINUE;
    END IF;

    -- Prefer the existing historical link for this original printed reference and the SAME person.
    SELECT count(DISTINCT l.book_id),(array_agg(l.book_id))[1] INTO matched,book_uuid
      FROM public.legacy_collection_imports l
      JOIN public.book_assignments a ON a.id=l.assignment_id AND a.deleted_at IS NULL
      JOIN public.books b ON b.id=l.book_id AND b.deleted_at IS NULL AND b.edition_id=edition_uuid
      WHERE l.status='IMPORTED' AND l.source_key LIKE 'Book3_v1:Sheet1:%'
        AND a.collector_id=person_uuid AND l.person_id=person_uuid
        AND (l.source_data||coalesce(l.source_corrections,'{}'::jsonb))->>'Book No.'=src.book_number::text;
    IF matched>1 THEN
      UPDATE pg_temp.dms_corrected84 SET result='Multiple historical book links match; review required'
        WHERE source_row=src.source_row; CONTINUE;
    END IF;
    IF matched=0 THEN
      SELECT count(*),(array_agg(b.id))[1] INTO matched,book_uuid
      FROM public.books b JOIN public.master_records m ON m.id=b.edition_id
      WHERE b.edition_id=edition_uuid AND b.deleted_at IS NULL AND
        CASE WHEN src.book_type='REGULAR' THEN
          b.receipt_from=CASE WHEN src.edition_number<=5 THEN 1+(src.book_number::bigint-1)*50
            ELSE m.pages_from+(src.book_number::bigint-1)*50 END
        ELSE b.edition_book_number=src.book_number END;
      IF matched<>1 OR EXISTS (SELECT 1 FROM public.books b WHERE b.id=book_uuid AND b.status<>'IN_STOCK')
        OR EXISTS (SELECT 1 FROM public.book_cases c WHERE c.book_id=book_uuid)
        OR EXISTS (SELECT 1 FROM public.book_returns r WHERE r.book_id=book_uuid)
        OR EXISTS (SELECT 1 FROM public.book_receipts r WHERE r.book_id=book_uuid)
        OR EXISTS (SELECT 1 FROM pg_temp.dms_corrected84 plan WHERE plan.book_id=book_uuid
          AND (plan.person_id<>person_uuid OR plan.book_number<>src.book_number)) THEN
        book_uuid:=NULL;
      END IF;
      -- Reuse this batch's allocation for duplicate rows referring to the same physical book/person.
      SELECT coalesce((SELECT plan.book_id FROM pg_temp.dms_corrected84 plan
        WHERE plan.person_id=person_uuid AND plan.edition_id=edition_uuid AND plan.book_number=src.book_number
          AND plan.book_id IS NOT NULL ORDER BY plan.source_row LIMIT 1),book_uuid) INTO book_uuid;
      IF book_uuid IS NULL THEN
        UPDATE pg_temp.dms_corrected84 SET result='Original printed book reference is missing, ambiguous, or already belongs to another assignment; no substitute book was allocated'
          WHERE source_row=src.source_row; CONTINUE;
      END IF;
    END IF;
    SELECT * INTO stock FROM public.books WHERE id=book_uuid;
    note_text:=format('Matched existing book %s (receipts %s-%s); original printed reference %s retained',
      stock.book_number,stock.receipt_from,stock.receipt_to,src.book_number);
    SELECT count(*),(array_agg(m.id ORDER BY (m.name_en=src.collection_area) DESC,m.id))[1] INTO matched,area_uuid
      FROM public.master_records m WHERE m.kind='AREA' AND m.level='COLLECTION' AND m.active AND m.deleted_at IS NULL
        AND lower(btrim(m.name_en))=lower(btrim(src.collection_area));
    IF matched=0 THEN
      INSERT INTO public.master_records(kind,code,name_en,name_ur,level,active,created_by,updated_by)
      VALUES('AREA','AREA_'||upper(md5(src.collection_area)),src.collection_area,src.collection_area,
        'COLLECTION',true,actor.id,actor.id) RETURNING id INTO area_uuid;
    ELSIF matched>1 AND NOT EXISTS (SELECT 1 FROM public.master_records m WHERE m.id=area_uuid AND m.name_en=src.collection_area) THEN
      UPDATE pg_temp.dms_corrected84 SET result='Ambiguous collection area; review required'
        WHERE source_row=src.source_row; CONTINUE;
    END IF;
    UPDATE pg_temp.dms_corrected84 SET person_id=person_uuid,edition_id=edition_uuid,area_id=area_uuid,
      book_id=book_uuid,allocation_note=note_text WHERE source_row=src.source_row;
  END LOOP;

  -- Same historical-import workflow as 0023. Keep FK/CHECK/RLS, amount calculation,
  -- certificate issuance, and audit triggers active. Restore all six workflow triggers atomically.
  IF (SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname='public' AND NOT t.tgisinternal AND t.tgenabled='O' AND (c.relname,t.tgname) IN (
      ('book_assignments','prepare_book_assignment'),('book_assignments','allocate_assignment_books'),
      ('book_returns','prepare_book_return'),('book_returns','finish_book_return'),
      ('book_receipts','guard_book_receipt'),('book_receipts','aa_open_receipt_range')))<>6 THEN
    RAISE EXCEPTION 'Expected six enabled historical-import workflow triggers; no changes committed';
  END IF;
  ALTER TABLE public.book_assignments DISABLE TRIGGER prepare_book_assignment;
  ALTER TABLE public.book_assignments DISABLE TRIGGER allocate_assignment_books;
  ALTER TABLE public.book_returns DISABLE TRIGGER prepare_book_return;
  ALTER TABLE public.book_returns DISABLE TRIGGER finish_book_return;
  ALTER TABLE public.book_receipts DISABLE TRIGGER guard_book_receipt;
  ALTER TABLE public.book_receipts DISABLE TRIGGER aa_open_receipt_range;

  FOR group_row IN SELECT book_id,person_id FROM pg_temp.dms_corrected84
    WHERE result='' AND book_id IS NOT NULL GROUP BY book_id,person_id ORDER BY book_id,person_id LOOP
    BEGIN
      SELECT * INTO stock FROM public.books WHERE id=group_row.book_id FOR UPDATE;
      SELECT sum(amount_paise),sum(commission_paise),count(*) FILTER(WHERE amount_paise>0),
        min(collection_date),max(collection_date),min(entry_date),max(entry_date),
        string_agg(DISTINCT entry_by,' / ' ORDER BY entry_by)
        INTO new_total,new_commission,added_receipts,first_day,last_day,first_entry,last_entry,staff_text
        FROM pg_temp.dms_corrected84 WHERE book_id=stock.id AND result='';
      SELECT p.full_name,f.code,coalesce(p.phone,''),coalesce(f.whatsapp,''),
        concat_ws(', ',nullif(f.village,''),nullif(f.post_office,''),nullif(f.block,''),nullif(f.district,''),nullif(f.state,''),nullif(f.pin,''))
        INTO name_text,code_text,phone_text,whatsapp_text,address_text
        FROM public.people p JOIN public.fundraisers f ON f.person_id=p.id WHERE p.id=group_row.person_id;
      SELECT jsonb_agg(jsonb_build_object('id',m.id,'nameEn',m.name_en,'nameUr',m.name_ur) ORDER BY m.name_en,m.id)
        INTO areas_json FROM public.master_records m WHERE m.id IN
          (SELECT area_id FROM pg_temp.dms_corrected84 WHERE book_id=stock.id AND result='');
      return_uuid:=NULL; prior_total:=0; prior_commission:=0; return_before:=NULL;
      SELECT count(*),(array_agg(r.id))[1] INTO matched,return_uuid FROM public.book_returns r
        JOIN public.book_assignments a ON a.id=r.assignment_id AND a.deleted_at IS NULL
        WHERE r.book_id=stock.id AND r.deleted_at IS NULL AND a.collector_id=group_row.person_id;
      IF matched=0 THEN
        IF stock.status<>'IN_STOCK' OR EXISTS (SELECT 1 FROM public.book_cases WHERE book_id=stock.id)
          OR EXISTS (SELECT 1 FROM public.book_receipts WHERE book_id=stock.id) THEN
          RAISE EXCEPTION 'Existing assignment or receipt history requires review' USING ERRCODE='P3101';
        END IF;
        assignment_uuid:=gen_random_uuid(); case_uuid:=gen_random_uuid(); return_uuid:=gen_random_uuid();
        INSERT INTO public.book_assignments(id,assignment_date,expected_return_date,collector_id,collector_name,
          collector_code,phone,whatsapp,address,areas,book_ids,remarks,assigned_by_name,operation_id,operation_hash,
          created_at,updated_at,created_by,updated_by)
        VALUES(assignment_uuid,first_day,(first_day+interval '11 months')::date,group_row.person_id,name_text,
          code_text,phone_text,whatsapp_text,address_text,areas_json,jsonb_build_array(stock.id),
          'Corrected historical import. Collection date used as assumed assignment date; receipt numbers assumed from book start.',
          staff_text,gen_random_uuid(),encode(sha256(convert_to('corrected84:'||stock.id::text,'UTF8')),'hex'),
          first_entry::timestamp AT TIME ZONE 'Asia/Kolkata',last_entry::timestamp AT TIME ZONE 'Asia/Kolkata',actor.id,actor.id);
        INSERT INTO public.book_cases(id,assignment_id,book_id,receipt_from,receipt_to,source,source_code,created_at)
        VALUES(case_uuid,assignment_uuid,stock.id,stock.receipt_from,stock.receipt_to,'NEW',stock.book_number,
          first_entry::timestamp AT TIME ZONE 'Asia/Kolkata');
        INSERT INTO public.book_returns(id,case_id,source_code,submission_pending,book_id,assignment_id,book_number,
          collector_name,return_date,outcome,total_paise,cash_paise,digital_paise,receipt_sum_paise,
          receipt_from,receipt_to,receipts_used,last_used,commission_basis_points,historical_commission_paise,
          commission_given,remarks,checked_by_name,receipt_entry_status,operation_id,operation_hash,
          created_at,updated_at,created_by,updated_by)
        VALUES(return_uuid,case_uuid,stock.book_number,true,stock.id,assignment_uuid,stock.book_number,name_text,last_day,
          'PARTLY_USED',new_total,new_total,0,new_total,stock.receipt_from,stock.receipt_to,0,NULL,0,new_commission,
          new_commission>0,'Historical collections from corrected 84-row workbook; cash assumed; actual receipt numbers unknown.',
          staff_text,'DRAFT',gen_random_uuid(),encode(sha256(convert_to('corrected84:return:'||stock.id::text,'UTF8')),'hex'),
          first_entry::timestamp AT TIME ZONE 'Asia/Kolkata',last_entry::timestamp AT TIME ZONE 'Asia/Kolkata',actor.id,actor.id);
        receipt_no:=stock.receipt_from;
      ELSE
        SELECT * INTO returned FROM public.book_returns WHERE id=return_uuid FOR UPDATE;
        return_before:=to_jsonb(returned); assignment_uuid:=returned.assignment_id; case_uuid:=returned.case_id;
        IF matched<>1 OR returned.reopened_at IS NOT NULL OR stock.status IN ('LOST','FLAGGED','PARTLY_USED','LEFTOVER_ASSIGNED')
          OR EXISTS (SELECT 1 FROM public.book_cases c WHERE c.book_id=stock.id AND c.id<>case_uuid)
          OR EXISTS (SELECT 1 FROM public.leftover_books l WHERE l.book_id=stock.id AND l.deleted_at IS NULL)
          OR EXISTS (SELECT 1 FROM public.book_flags f WHERE f.book_id=stock.id AND f.deleted_at IS NULL AND f.status<>'RESOLVED')
          OR EXISTS (SELECT 1 FROM public.receipt_issues i WHERE i.return_id=return_uuid AND i.status='OPEN')
          OR returned.cash_paise<>returned.total_paise OR returned.digital_paise<>0
          OR NOT EXISTS (SELECT 1 FROM public.legacy_collection_imports l
            WHERE l.return_id=return_uuid AND l.status='IMPORTED' AND l.person_id=group_row.person_id)
          OR EXISTS (SELECT 1 FROM public.book_receipts r WHERE r.return_id=return_uuid
            AND (r.deleted_at IS NOT NULL OR r.checked OR r.version<>1 OR r.status<>'VALID'
              OR r.data->>'paymentMode' IS DISTINCT FROM 'CASH'
              OR NOT EXISTS (SELECT 1 FROM public.legacy_collection_imports l WHERE l.receipt_id=r.id
                AND l.status='IMPORTED' AND l.book_id=stock.id AND l.person_id=group_row.person_id
                AND l.assumed_receipt_number=r.receipt_number
                AND r.amount_paise=((l.source_data||coalesce(l.source_corrections,'{}'::jsonb))->>'Collection Amount')::numeric*100)))
          OR returned.total_paise<>(SELECT coalesce(sum(r.amount_paise),0) FROM public.book_receipts r
            WHERE r.return_id=return_uuid AND r.deleted_at IS NULL) THEN
          RAISE EXCEPTION 'Existing book was edited, checked, reopened, reassigned or has unresolved history; preserved for review'
            USING ERRCODE='P3101';
        END IF;
        prior_total:=returned.total_paise; prior_commission:=returned.commission_paise;
        SELECT coalesce(max(r.receipt_number)+1,returned.receipt_from) INTO receipt_no
          FROM public.book_receipts r WHERE r.return_id=return_uuid;
        -- No old receipt is rewritten. The normal receipt audit remains enabled.
        UPDATE public.book_returns SET finalized_at=NULL,submission_pending=true,
          total_paise=prior_total+new_total,cash_paise=prior_total+new_total,
          receipt_sum_paise=prior_total+new_total,historical_commission_paise=prior_commission+new_commission,
          commission_given=prior_commission+new_commission>0,updated_at=now(),updated_by=actor.id WHERE id=return_uuid;
        -- Keep the existing assignment/certificate numbers and dates; add any newly recorded collection areas.
        UPDATE public.book_assignments a SET areas=(SELECT jsonb_agg(value ORDER BY value->>'nameEn',value->>'id')
          FROM (SELECT DISTINCT ON (value->>'id') value FROM jsonb_array_elements(a.areas||areas_json)) unique_areas),
          updated_at=now(),updated_by=actor.id WHERE a.id=assignment_uuid;
      END IF;
      IF prior_total+new_total>999999999999 OR receipt_no+added_receipts-1>stock.receipt_to THEN
        RAISE EXCEPTION 'Collection total or assumed receipt count exceeds book capacity' USING ERRCODE='P3101';
      END IF;
      FOR line IN SELECT * FROM pg_temp.dms_corrected84 WHERE book_id=stock.id AND result='' ORDER BY source_row LOOP
        receipt_uuid:=NULL;
        IF line.amount_paise>0 THEN
          IF EXISTS (SELECT 1 FROM public.book_receipts r WHERE r.book_id=stock.id AND r.receipt_number=receipt_no) THEN
            RAISE EXCEPTION 'Assumed receipt number is already in use' USING ERRCODE='P3101';
          END IF;
          receipt_uuid:=gen_random_uuid();
          note_text:='HISTORICAL SUMMARY; actual receipt number unknown. Corrected workbook original Excel row '||
            line.source_row::text||'. Book condition: '||line.condition||'. Collection area: '||line.collection_area||
            '. Exact commission INR '||to_char(line.commission_paise::numeric/100,'FM999999999990.00')||
            '. Cash assumed. '||line.allocation_note||'. '||line.note;
          INSERT INTO public.book_receipts(id,return_id,book_id,receipt_number,checked,data,labels,status,amount_paise,
            phone,entry_by_name,created_at,updated_at,created_by,updated_by)
          VALUES(receipt_uuid,return_uuid,stock.id,receipt_no,false,jsonb_build_object(
            'status','VALID','date',line.collection_date::text,'reasonId','','anonymous',false,
            'donorName','','parentage','S/O','parentName','','phone','','email','','marhoomName','','pan','',
            'village','','postOffice','','block','','district',line.collection_area,'state',coalesce(line.corrections->>'State',''),
            'pin','','amountPaise',line.amount_paise,'amountWords','','paymentMode','CASH',
            'upiAppId','','reference','','transactionDate','','chequeNumber','','bankId','','branch','','chequeDate','',
            'heads','[]'::jsonb,'receiverName',name_text,'responsibility','','donorSigned',false,'receiverSigned',false,
            'remarks',note_text),'{}'::jsonb,'VALID',line.amount_paise,'',line.entry_by,
            line.entry_date::timestamp AT TIME ZONE 'Asia/Kolkata',line.entry_date::timestamp AT TIME ZONE 'Asia/Kolkata',actor.id,actor.id);
        END IF;
        UPDATE public.legacy_collection_imports SET status='IMPORTED',person_id=group_row.person_id,book_id=stock.id,
          assignment_id=assignment_uuid,return_id=return_uuid,receipt_id=receipt_uuid,
          assumed_receipt_number=CASE WHEN receipt_uuid IS NOT NULL THEN receipt_no END,imported_at=now(),
          reason=CASE WHEN receipt_uuid IS NULL THEN 'Zero collection; no receipt consumed'
            ELSE 'Historical summary; receipt number assumed' END||'; '||line.allocation_note||'; '||line.note
          WHERE source_key='Book3_v1:Sheet1:'||line.source_row::text;
        UPDATE pg_temp.dms_corrected84 SET newly_imported=true,result='Imported'
          WHERE source_row=line.source_row;
        IF receipt_uuid IS NOT NULL THEN receipt_no:=receipt_no+1; END IF;
      END LOOP;
      SELECT count(*),max(r.receipt_number) INTO used_receipts,last_receipt FROM public.book_receipts r
        WHERE r.return_id=return_uuid AND r.deleted_at IS NULL;
      SELECT coalesce(nullif(effective->>'Book Condition',''),'Blank') INTO final_condition
        FROM (SELECT l.source_row,l.source_data||coalesce(l.source_corrections,'{}'::jsonb) AS effective
          FROM public.legacy_collection_imports l WHERE l.return_id=return_uuid AND l.status='IMPORTED') history
        ORDER BY left(effective->>'Collection Date',10) DESC NULLS LAST,source_row DESC LIMIT 1;
      IF final_condition='Not Used' AND (prior_total+new_total<>0 OR used_receipts<>0) THEN
        RAISE EXCEPTION 'Not Used conflicts with other collections in this book; review required' USING ERRCODE='P3101';
      END IF;
      UPDATE public.book_returns SET return_date=greatest(return_date,last_day),receipts_used=used_receipts,last_used=last_receipt,
        outcome=CASE WHEN final_condition IN ('Finished','Blank') THEN 'CLOSED' ELSE 'PARTLY_USED' END,
        receipt_entry_status=CASE WHEN final_condition='Continue' THEN 'DRAFT' ELSE 'RECONCILED' END,
        submission_pending=final_condition='Continue',
        finalized_at=CASE WHEN final_condition='Continue' THEN NULL ELSE coalesce((return_before->>'finalized_at')::timestamptz,now()) END,
        receipt_entry_version=receipt_entry_version+1,updated_at=now(),updated_by=actor.id
        WHERE id=return_uuid;
      UPDATE public.book_cases SET closed_at=CASE WHEN final_condition='Continue' THEN NULL ELSE coalesce(closed_at,now()) END WHERE id=case_uuid;
      UPDATE public.books SET status=CASE WHEN final_condition='Continue' THEN 'ASSIGNED'
        WHEN final_condition='Not Used' THEN 'PARTLY_USED' ELSE 'CLOSED' END,updated_at=now(),updated_by=actor.id WHERE id=stock.id;
      IF final_condition='Not Used' THEN
        SELECT coalesce(max(l.ordinal),0)+1 INTO next_ordinal FROM public.leftover_books l WHERE l.book_id=stock.id;
        INSERT INTO public.leftover_books(book_id,return_id,returned_by,code,ordinal,receipt_from,receipt_to,status,created_by,updated_by)
        VALUES(stock.id,return_uuid,group_row.person_id,stock.book_number||'-B'||next_ordinal,next_ordinal,
          stock.receipt_from,stock.receipt_to,'AVAILABLE',actor.id,actor.id);
      END IF;
      INSERT INTO public.activity_log(actor_id,action,resource,record_id,old_values,new_values,reason,created_by,updated_by)
        SELECT actor.id,CASE WHEN return_before IS NULL THEN 'INSERT' ELSE 'UPDATE' END,'book_returns',r.id::text,return_before,to_jsonb(r),
          'Corrected 84-row historical workbook; original ledger and issued numbers preserved',actor.id,actor.id
        FROM public.book_returns r WHERE r.id=return_uuid;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS problem=MESSAGE_TEXT,failure_state=RETURNED_SQLSTATE;
      IF failure_state NOT IN ('P3101','23505','23P01') THEN RAISE; END IF;
      UPDATE pg_temp.dms_corrected84 SET result=problem,newly_imported=false
        WHERE book_id=group_row.book_id AND NOT previously_imported;
    END;
  END LOOP;

  ALTER TABLE public.book_assignments ENABLE TRIGGER prepare_book_assignment;
  ALTER TABLE public.book_assignments ENABLE TRIGGER allocate_assignment_books;
  ALTER TABLE public.book_returns ENABLE TRIGGER prepare_book_return;
  ALTER TABLE public.book_returns ENABLE TRIGGER finish_book_return;
  ALTER TABLE public.book_receipts ENABLE TRIGGER guard_book_receipt;
  ALTER TABLE public.book_receipts ENABLE TRIGGER aa_open_receipt_range;
  UPDATE public.legacy_collection_imports l SET reason=coalesce(nullif(i.result,''),'Pending review')
    FROM pg_temp.dms_corrected84 i WHERE l.source_key='Book3_v1:Sheet1:'||i.source_row::text
      AND l.status='SKIPPED';

  -- Every successful row must link to the intended person/book/submission and exact amount.
  IF EXISTS (SELECT 1 FROM pg_temp.dms_corrected84 i JOIN public.legacy_collection_imports l
    ON l.source_key='Book3_v1:Sheet1:'||i.source_row::text
    LEFT JOIN public.book_returns r ON r.id=l.return_id
    LEFT JOIN public.book_assignments a ON a.id=l.assignment_id
    LEFT JOIN public.book_receipts receipt ON receipt.id=l.receipt_id
    WHERE i.newly_imported AND (l.status<>'IMPORTED' OR l.person_id IS DISTINCT FROM i.person_id
      OR a.collector_id IS DISTINCT FROM i.person_id OR l.book_id IS DISTINCT FROM i.book_id
      OR r.book_id IS DISTINCT FROM i.book_id OR r.assignment_id IS DISTINCT FROM a.id
      OR (i.amount_paise>0 AND (receipt.id IS NULL OR receipt.amount_paise<>i.amount_paise
        OR receipt.return_id<>r.id OR receipt.book_id<>i.book_id))
      OR (i.amount_paise=0 AND l.receipt_id IS NOT NULL))) THEN
    RAISE EXCEPTION 'Import integrity mismatch; entire transaction rolled back';
  END IF;
END;
$corrected84$;

SELECT count(*) AS workbook_rows,
  count(*) FILTER(WHERE previously_imported) AS already_imported_unchanged,
  count(*) FILTER(WHERE newly_imported) AS newly_imported_rows,
  count(*) FILTER(WHERE NOT previously_imported AND NOT newly_imported) AS pending_rows,
  coalesce(sum(amount_paise) FILTER(WHERE newly_imported),0)/100.0 AS newly_added_collection_inr,
  coalesce(sum(commission_paise) FILTER(WHERE newly_imported),0)/100.0 AS newly_added_commission_inr,
  coalesce(jsonb_agg(jsonb_build_object('excel_row',source_row,'fundraiser',canonical_name,
    'original_book',book_number,'edition',edition_number,'reason',result) ORDER BY source_row)
    FILTER(WHERE NOT previously_imported AND NOT newly_imported),'[]'::jsonb) AS pending_details,
  coalesce(jsonb_agg(jsonb_build_object('excel_row',source_row,'fundraiser',canonical_name,'allocation',allocation_note)
    ORDER BY source_row) FILTER(WHERE newly_imported),'[]'::jsonb) AS matched_books
FROM pg_temp.dms_corrected84;
COMMIT;

